// ─── Stage 1: Hand-written Lexer ────────────────────────────────────────────
function lex(source) {
  const tokens = [];
  let i = 0;
  let line = 1;

  while (i < source.length) {
    // Track newlines for error position
    if (source[i] === '\n') { line++; i++; continue; }

    // Skip other whitespace
    if (/[ \t\r]/.test(source[i])) { i++; continue; }

    // Number literal: maximal munch over digits
    if (/[0-9]/.test(source[i])) {
      let num = '';
      const startLine = line;
      while (i < source.length && /[0-9]/.test(source[i])) num += source[i++];
      tokens.push({ type: 'NUMBER', value: Number(num), line: startLine });
      continue;
    }

    // Identifier or keyword
    if (/[a-zA-Z_]/.test(source[i])) {
      let word = '';
      const startLine = line;
      while (i < source.length && /[\w]/.test(source[i])) word += source[i++];
      const KEYWORDS = new Set(['let', 'const', 'if', 'else', 'return', 'while']);
      tokens.push({
        type: KEYWORDS.has(word) ? 'KEYWORD' : 'IDENT',
        value: word,
        line: startLine
      });
      continue;
    }

    // Two-character operators (maximal munch: check == before =)
    if (source.slice(i, i + 2) === '==') {
      tokens.push({ type: 'EQEQ', value: '==', line });
      i += 2;
      continue;
    }

    // Single-character tokens
    const SINGLE = {
      '=': 'EQ', '+': 'PLUS', '-': 'MINUS',
      '*': 'STAR', '/': 'SLASH', ';': 'SEMI',
      '(': 'LPAREN', ')': 'RPAREN'
    };
    if (SINGLE[source[i]]) {
      tokens.push({ type: SINGLE[source[i]], value: source[i], line });
      i++;
      continue;
    }

    // Unrecognised character → lexical error
    throw new SyntaxError(
      `Lexical error: unexpected character '${source[i]}' at line ${line}`
    );
  }

  tokens.push({ type: 'EOF', value: null, line });
  return tokens;
}

// Test the lexer
const src = 'let total = 10 + 32;';
const tokens = lex(src);
console.log(tokens.map(t => `${t.type}(${t.value})`).join(' '));
// KEYWORD(let) IDENT(total) EQ(=) NUMBER(10) PLUS(+) NUMBER(32) SEMI(;) EOF(null)

// ─── Stage 2: Recursive Descent Parser ──────────────────────────────────────
function parse(tokens) {
  let pos = 0;

  const peek = ()  => tokens[pos];
  const advance = () => tokens[pos++];
  const expect = (type) => {
    const tok = peek();
    if (tok.type !== type)
      throw new SyntaxError(
        `Syntax error at line ${tok.line}: expected ${type}, got ${tok.type}('${tok.value}')`
      );
    return advance();
  };

  // program ::= statement* EOF
  function parseProgram() {
    const body = [];
    while (peek().type !== 'EOF') body.push(parseStatement());
    return { type: 'Program', body };
  }

  // statement ::= letDecl | exprStmt
  function parseStatement() {
    if (peek().type === 'KEYWORD' && peek().value === 'let') return parseLetDecl();
    return parseExprStmt();
  }

  // letDecl ::= 'let' IDENT '=' expression ';'
  function parseLetDecl() {
    expect('KEYWORD');             // consume 'let'
    const name = expect('IDENT'); // variable name
    expect('EQ');                  // consume '='
    const init = parseExpression();
    expect('SEMI');
    return { type: 'LetDeclaration', name: name.value, init };
  }

  // exprStmt ::= expression ';'
  function parseExprStmt() {
    const expr = parseExpression();
    expect('SEMI');
    return { type: 'ExprStatement', expr };
  }

  // expression ::= term (('+' | '-') term)*
  function parseExpression() {
    let left = parseTerm();
    while (peek().type === 'PLUS' || peek().type === 'MINUS') {
      const op = advance().value;
      const right = parseTerm();
      left = { type: 'BinaryExpr', op, left, right };
    }
    return left;
  }

  // term ::= factor (('*' | '/') factor)*
  function parseTerm() {
    let left = parseFactor();
    while (peek().type === 'STAR' || peek().type === 'SLASH') {
      const op = advance().value;
      const right = parseFactor();
      left = { type: 'BinaryExpr', op, left, right };
    }
    return left;
  }

  // factor ::= NUMBER | IDENT | '(' expression ')'
  function parseFactor() {
    if (peek().type === 'NUMBER') return { type: 'Literal', value: advance().value };
    if (peek().type === 'IDENT')  return { type: 'Identifier', name: advance().value };
    if (peek().type === 'LPAREN') {
      advance(); // consume '('
      const expr = parseExpression();
      expect('RPAREN');
      return expr;
    }
    const tok = peek();
    throw new SyntaxError(`Syntax error at line ${tok.line}: unexpected token ${tok.type}`);
  }

  return parseProgram();
}

