// ─── Evaluating the AST — a simple tree-walk interpreter ───────────────────
function evaluate(node, env = {}) {
  switch (node.type) {
    case 'Program':
      let result;
      for (const stmt of node.body) result = evaluate(stmt, env);
      return result;

    case 'LetDeclaration': {
      const val = evaluate(node.init, env);
      env[node.name] = val;
      return val;
    }

    case 'ExprStatement':
      return evaluate(node.expr, env);

    case 'BinaryExpr': {
      const l = evaluate(node.left, env);
      const r = evaluate(node.right, env);
      if (node.op === '+') return l + r;
      if (node.op === '-') return l - r;
      if (node.op === '*') return l * r;
      if (node.op === '/') return l / r;
      throw new Error(`Unknown operator: ${node.op}`);
    }

    case 'Literal':
      return node.value;

    case 'Identifier':
      if (!(node.name in env))
        throw new ReferenceError(`Undefined variable: ${node.name}`);
      return env[node.name];

    default:
      throw new Error(`Unknown AST node type: ${node.type}`);
  }
}

// Full pipeline: source → tokens → AST → result
const program = 'let total = 10 + 32;';
const result = evaluate(parse(lex(program)));
console.log(result); // 42

